export const MONUMENTS = JSON.parse("[{\"id\":\"n808014174\",\"kind\":\"memorial\",\"sub\":\"stele\",\"name\":\"Колонна Славы\",\"x\":-2470.7,\"z\":1777.2,\"wikidata\":\"Q2077375\",\"wikipedia\":\"ru:Колонна Славы\"},{\"id\":\"n1352565268\",\"kind\":\"memorial\",\"sub\":\"stele\",\"name\":\"памятник Человеку-невидимке (ранее Александру II)\",\"x\":-2737,\"z\":1655,\"material\":\"stone\"},{\"id\":\"n4351117193\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"В. П. Стасов\",\"x\":-2471.4,\"z\":1735.5,\"subject\":\"Q552476\",\"inscription\":\"Архитектору Стасову 1769–1848\"},{\"id\":\"n6469057986\",\"kind\":\"artwork\",\"sub\":\"fountain\",\"name\":\"Памятник петербургскому дождю\",\"x\":-2339,\"z\":1790.4},{\"id\":\"n1107412254\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Г. В. Плеханов\",\"x\":-1826.7,\"z\":1686.3,\"subject\":\"Q182905\",\"inscription\":\"1856-1918\"},{\"id\":\"n5752062653\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. Д. Зелинскому\",\"x\":-1882.1,\"z\":1654.3,\"subject\":\"Q435709\",\"inscription\":\"Здесь в 1915 году выдающийся ученый Николай Дмитриевич Зелинский изобрел угольный противогаз\"},{\"id\":\"n6517079213\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. И. Менделееву\",\"x\":-1845.7,\"z\":1646.2,\"subject\":\"Q9106\",\"inscription\":\"Здесь жил и работал в 1863–1872 годы великий русский учёный, создатель периодической системы элементов Дмитрий Иванович Менделеев (1834–1907)\"},{\"id\":\"n6517079214\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. К. Чернову\",\"x\":-1845.8,\"z\":1641.4,\"subject\":\"Q738334\",\"inscription\":\"Здесь в 1859–1866 годы работал выдающийся русский учёный, основоположник теории металлургических процессов Дмитрий Константинович Чернов (1839–1921)\"},{\"id\":\"n6517079216\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. М. Кржижановскому\",\"x\":-1843,\"z\":1655.8,\"subject\":\"Q944478\",\"inscription\":\"Здесь с 1889 г. по 1894 г. учился и начал свою революционную работу в марксистском кружке студентов-технологов старейший деятель революционного движения, крупный учёный-энергетик Глеб Максимилианович Кржижановский\"},{\"id\":\"n6517079218\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-1797.2,\"z\":1678.8,\"subject\":\"Q1394\",\"inscription\":\"В 1905–1906 гг. В.И. Ленин неоднократно выступал в здании Технологического института на партийных собраниях Петербургской социал-демократической организации по вопросам тактики большевиков в буржуазно-демократической революции\"},{\"id\":\"n6517079219\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. П. Горбунову\",\"x\":-1782.6,\"z\":1675.5,\"subject\":\"Q4811867\",\"inscription\":\"Здесь, в Технологическом институте, в 1910–1917 гг. учился Николай Петрович Горбунов, советский государственный деятель, один из организаторов науки, академик\"},{\"id\":\"n6517079220\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. Варыньскому\",\"x\":-1774.4,\"z\":1669.7,\"subject\":\"Q1875503\",\"inscription\":\"Здесь, в Петербургском технологическом институте, в 1874–1875 годах учился Людвик Варыньский — деятель социалистического движения, основатель польской партии «Пролетариат» (1882). Погиб в Шлиссельбургской крепости в 1889 году.\"},{\"id\":\"n8936464851\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. Ф. Устинову\",\"x\":-2010.4,\"z\":1799.8,\"subject\":\"Q48067\",\"inscription\":\"В этом здании с 1930 по 1934 годы учился маршал Советского Союза Дмитрий Федорович Устинов\"},{\"id\":\"n6570418415\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-2994.9,\"z\":1748.8},{\"id\":\"n6570418416\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-3039.1,\"z\":1768.8},{\"id\":\"n6570418417\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-3045.2,\"z\":1706.3},{\"id\":\"n6570418418\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-3001.6,\"z\":1686},{\"id\":\"n11677773835\",\"kind\":\"artwork\",\"sub\":\"graffiti\",\"name\":\"Алиса в стране чудес\",\"x\":-2989,\"z\":1642.4},{\"id\":\"n5611917925\",\"kind\":\"memorial\",\"sub\":\"stele\",\"name\":\"Памятный знак «От „Дельфина“ до „Тайфуна“»\",\"x\":-784.9,\"z\":1761.6,\"startDate\":\"2000-11-02\",\"inscription\":\"ЦКБ Морской Техники «Рубин» 1901-2001 от «Дельфина» до «Тайфуна»\"},{\"id\":\"n5686902648\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. Н. Ковалеву\",\"x\":-811.7,\"z\":1726.7,\"subject\":\"Q2425827\",\"inscription\":\"В этом здании с 1959 по 2011 год работал дважды герой социалистического труда, генеральный конструктор ракетных подводных крейсеров стратегического назначения, академик Сергей Никитич Ковалев\"},{\"id\":\"n6566674359\",\"kind\":\"memorial\",\"sub\":\"war_memorial\",\"name\":\"Памятник сотрудникам типографии им. Ивана Фёдорова, погибшим в годы ВОВ\",\"x\":-537.5,\"z\":1694.8,\"startDate\":\"1967\",\"artist\":\"В. И. Лапоногов\",\"inscription\":\"Рабочим, инженерам, техническим работникам и служащим ордена Трудового Красного Знамени типографии имени Ивана Федорова, отдавшим жизни за счастье народа в годы Великой Отечественной войны и блокады Ленинграда. 1941–1945\"}]");
